(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-992":{scenario:{company:"Công ty Đường sắt Đô thị Ánh Dương",supervisor:{name:"Lương Thị Kim Oanh",role:{vi:"Trưởng ca Trung tâm Điều độ",en:"OCC Shift Manager"}},ref_code:"OCC-1408",title:{vi:"Đúng chế độ lái. Đủ đoàn tàu. Không đánh đổi an toàn lấy giãn cách.",en:"Right driving mode. Enough trains. Never trade safety for headway."},brief:{vi:"Giờ cao điểm, tuyến số 2 (mô phỏng) cần giãn cách 4 phút. Thời gian chạy một chiều 28,5 phút, thời gian quay đầu tại mỗi ga cuối 4 phút. Đoàn tàu T09 mất liên lạc CBTC giữa ga S06 và S07, không còn cấp phép di chuyển từ hệ thống. Bản nháp lệnh điều độ OCC-1408 cho T09 chạy chế độ CM và tính 15 đoàn tàu vận doanh. Đối chiếu quy trình điều độ đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"At peak time, line 2 (training) needs a 4-minute headway. One-way running time is 28.5 minutes and turnback time at each terminus is 4 minutes. Train T09 has lost CBTC communication between stations S06 and S07 and no longer has a system movement authority. Draft dispatch order OCC-1408 sets T09 to CM mode and plans 15 trains in service. Compare it with the approved control procedure, correct both fields and write an evidence-based report."},reference_title:{vi:"Quy trình điều độ & biểu đồ chạy tàu đã duyệt · OCC-1408",en:"Approved control procedure & timetable · OCC-1408"},fields:[{id:"TRAIN_MODE",label:{vi:"Chế độ lái cho T09",en:"Driving mode for T09"},initial:"CM",expected:"RM",choices:["ATO","CM","RM"],reference:"Quy trình khi mất liên lạc CBTC",hint:{vi:"ATO và CM đều cần cấp phép di chuyển từ CBTC; khi mất liên lạc chỉ được chạy chế độ hạn chế tốc độ thấp theo lệnh điều độ.",en:"ATO and CM both need a CBTC movement authority; after a loss of communication only restricted low-speed mode under OCC authority is allowed."}},{id:"TRAINS_REQ",label:{vi:"Số đoàn tàu vận doanh cần (đoàn)",en:"Trains required in service"},initial:"15",expected:"17",reference:"Bảng lập biểu đồ chạy tàu",ref_value:{vi:"Giãn cách 4 phút; chạy một chiều 28,5 phút; quay đầu 4 phút tại mỗi ga cuối",en:"Headway 4 minutes; one-way running time 28.5 minutes; 4-minute turnback at each terminus"},hint:{vi:"Bản nháp chỉ tính thời gian chạy hai chiều, quên thời gian quay đầu ở hai ga cuối.",en:"The draft counted only running time both ways and forgot turnback time at both termini."}}],sop32:{vi:"Thời gian chu trình = 2 x thời gian chạy một chiều + 2 x thời gian quay đầu; số đoàn tàu vận doanh = chu trình ÷ giãn cách, làm tròn lên; chưa tính tàu dự phòng.",en:"Cycle time = 2 x one-way running time + 2 x turnback time; trains in service = cycle time ÷ headway, rounded up; spare trains not included."},context:{label:"OCC / OCC-1408",metrics:[{label:{vi:"Giãn cách mục tiêu",en:"Target headway"},value:"4 min"},{label:{vi:"Chạy một chiều",en:"One-way running time"},value:"28.5 min"},{label:{vi:"Quay đầu mỗi ga cuối",en:"Turnback per terminus"},value:"4 min"}]},crisis:{vi:"Phó giám đốc vận hành gọi: “Ke ga đang ùn khách, cho T09 cắt ATP chạy tay tốc độ thường cho nhanh. Còn trễ chuyến thì ghi dưới 5 phút thôi, khỏi phải báo cáo sự cố lên cơ quan quản lý.”",en:"The deputy operations director calls: “Platforms are overcrowded, let T09 cut out ATP and drive manually at normal speed. Log the delay as under 5 minutes so we don't have to report it to the regulator.”"},options:{safe:{vi:"Giữ T09 ở chế độ RM, giãn cách an toàn với tàu phía trước, thông báo hành khách, ghi đúng thời gian trễ và báo cáo sự cố theo quy trình, đề xuất tăng cường tàu khi CBTC phục hồi.",en:"Keep T09 in RM with safe spacing to the train ahead, inform passengers, record the true delay, report the incident per procedure and propose extra trains once CBTC recovers."},shortcut:{vi:"Cho T09 cắt ATP chạy tay tốc độ thường và ghi trễ dưới 5 phút.",en:"Let T09 cut out ATP at normal speed and log the delay as under 5 minutes."},wait:{vi:"Dừng mọi đoàn tàu, chờ hệ thống tự phục hồi và không thông báo gì.",en:"Hold all trains, wait for the system to recover and make no announcement."}},questions:{vi:["Vì sao T09 phải chạy chế độ RM chứ không phải CM? Điều kiện nào trong quy trình chứng minh?","Trình bày cách tính số đoàn tàu vận doanh và vì sao không được ghi giảm thời gian trễ."],en:["Why must T09 run in RM rather than CM? Which procedure condition proves it?","Explain how you calculated the trains in service and why the delay must not be under-reported."]},hints:{vi:["Kiểm tra T09 còn cấp phép di chuyển từ CBTC hay không, rồi đối chiếu bảng chế độ lái trong quy trình.","Tính thời gian chu trình đủ cả quay đầu theo SOP mục 3.2 rồi chia cho giãn cách, làm tròn lên.","Đọc lại SOP mục 4.2: không cắt thiết bị bảo vệ tàu và không sửa số liệu sự cố vì áp lực KPI."],en:["Check whether T09 still has a CBTC movement authority, then compare with the driving mode table.","Work out the full cycle including turnbacks per SOP 3.2, divide by the headway and round up.","Re-read SOP 4.2: never cut out train protection and never alter incident data for KPI reasons."]}},learning:{summary:{vi:"Chuyên viên điều độ đường sắt đô thị làm việc tại trung tâm điều độ (OCC), giám sát và điều hành chạy tàu theo biểu đồ, điều chỉnh giãn cách, xử lý sự cố tín hiệu, cửa chắn ke ga, cấp điện và tổ chức sơ tán hành khách. Nghề đòi hỏi hiểu hệ thống CBTC và các chế độ vận hành suy giảm, giao tiếp chuẩn qua vô tuyến và ra quyết định nhanh mà vẫn giữ nguyên tắc an toàn.",en:"An urban rail operations controller works in the operations control centre (OCC), supervising train service against the timetable, adjusting headways, handling signalling, platform screen door and power faults and organising passenger evacuation. The role requires knowledge of CBTC and degraded modes, standard radio communication and fast decisions that never compromise safety rules."},responsibilities:{vi:["Giám sát vị trí tàu, giãn cách và tình trạng hệ thống trên màn hình điều độ.","Điều chỉnh biểu đồ chạy tàu, bổ sung hoặc rút tàu khi nhu cầu thay đổi.","Cấp lệnh chạy tàu ở chế độ suy giảm khi tín hiệu, CBTC hoặc cửa chắn ke ga gặp sự cố.","Phối hợp điều độ điện, nhà ga, lái tàu và đội kỹ thuật khi xử lý sự cố.","Thông tin cho hành khách, ghi nhật ký điều độ và báo cáo sự cố đúng quy định."],en:["Monitor train positions, headways and system status on the control displays.","Adjust the timetable and insert or withdraw trains as demand changes.","Authorise degraded-mode operation when signalling, CBTC or platform screen doors fail.","Coordinate power control, stations, drivers and maintenance teams during incidents.","Inform passengers, keep the control log and report incidents as required."]},competencies:[{name:{vi:"Điều hành chạy tàu",en:"Train service control"},desc:{vi:"Giữ giãn cách đều, điều chỉnh thời gian dừng và xử lý tàu trễ để ổn định dịch vụ.",en:"Keep even headways, adjust dwell times and manage late trains to stabilise service."}},{name:{vi:"Vận hành suy giảm",en:"Degraded operations"},desc:{vi:"Áp dụng đúng chế độ lái, hạn chế tốc độ và quy tắc giãn cách khi hệ thống bị lỗi.",en:"Apply the correct driving mode, speed limits and spacing rules when systems fail."}},{name:{vi:"Giao tiếp an toàn",en:"Safety-critical communication"},desc:{vi:"Dùng mẫu câu chuẩn, nhắc lại và xác nhận lệnh qua vô tuyến để tránh hiểu nhầm.",en:"Use standard phrases, read-back and confirmation on the radio to avoid misunderstandings."}},{name:{vi:"Phân tích công suất tuyến",en:"Line capacity analysis"},desc:{vi:"Tính chu trình, số đoàn tàu và năng lực chuyên chở theo giãn cách mục tiêu.",en:"Calculate cycle time, fleet size and capacity for the target headway."}},{name:{vi:"Kỷ luật an toàn",en:"Safety discipline"},desc:{vi:"Không cắt thiết bị bảo vệ, không ghi sai số liệu và báo cáo đầy đủ mọi sự cố.",en:"Never bypass protection or falsify data and report every incident fully."}}],knowledge:{vi:["IEC 62290 về hệ thống quản lý và điều khiển vận tải đường ray đô thị, các cấp tự động hóa GoA0 đến GoA4.","IEEE 1474.1 về yêu cầu hiệu năng và chức năng của hệ thống CBTC.","Bộ tiêu chuẩn EN 50126, EN 50128, EN 50129 về RAMS và an toàn hệ thống tín hiệu đường sắt.","Pháp luật hiện hành về đường sắt và quy định khai thác đường sắt đô thị.","Cách tính thời gian chu trình, giãn cách, số đoàn tàu và năng lực chuyên chở giờ cao điểm."],en:["IEC 62290 on urban guided transport management and command systems and grades of automation GoA0 to GoA4.","IEEE 1474.1 on CBTC performance and functional requirements.","EN 50126, EN 50128 and EN 50129 on RAMS and railway signalling safety.","Current railway law and urban rail operating regulations.","Calculating cycle time, headway, fleet size and peak-hour capacity."]},tools:["Hệ thống giám sát tàu tự động (ATS)","Màn hình điều độ & sơ đồ tuyến","Hệ thống vô tuyến TETRA","Hệ thống SCADA cấp điện","Hệ thống thông tin hành khách (PIS)"],kpis:{vi:["Tỷ lệ chuyến tàu đúng giờ trong ngưỡng cho phép.","Mức tuân thủ giãn cách theo biểu đồ giờ cao điểm.","Thời gian khôi phục dịch vụ bình quân sau sự cố.","Số vi phạm quy trình an toàn trong điều độ (mục tiêu bằng 0)."],en:["Share of trips on time within the allowed tolerance.","Peak-hour headway adherence to the timetable.","Average service recovery time after incidents.","Safety procedure breaches in control operations (target zero)."]},day:[{time:"05:00",vi:"Nhận bàn giao ca, kiểm tra tình trạng hệ thống, tàu dự phòng và hạn chế tốc độ.",en:"Take the handover and check system status, spare trains and speed restrictions."},{time:"06:30",vi:"Điều hành giờ cao điểm sáng, theo dõi giãn cách và lưu lượng ke ga.",en:"Run the morning peak and monitor headways and platform crowding."},{time:"09:00",vi:"Rút bớt tàu về depot và phối hợp sửa chữa thiết bị ngoài giờ cao điểm.",en:"Withdraw trains to the depot and coordinate off-peak repairs."},{time:"11:30",vi:"Diễn tập tình huống mất liên lạc CBTC với lái tàu và nhà ga.",en:"Drill a CBTC communication loss with drivers and stations."},{time:"13:00",vi:"Ghi nhật ký điều độ, báo cáo sự kiện và bàn giao ca chiều.",en:"Complete the control log, report events and hand over to the afternoon shift."}],mistakes:{vi:["Cho tàu chạy chế độ CM hoặc cắt ATP khi không còn cấp phép di chuyển từ CBTC.","Lập biểu đồ quên thời gian quay đầu khiến thiếu tàu và giãn cách bị kéo dài.","Ghi giảm thời gian trễ hoặc không báo cáo sự cố để giữ chỉ số đúng giờ."],en:["Running a train in CM or cutting out ATP without a CBTC movement authority.","Planning without turnback time, leaving too few trains and longer headways.","Under-reporting delays or skipping incident reports to protect punctuality figures."]},career:[{vi:"Điều độ viên tập sự",en:"Trainee controller"},{vi:"Điều độ viên chạy tàu",en:"Train controller"},{vi:"Trưởng ca trung tâm điều độ",en:"OCC shift manager"},{vi:"Quản lý vận hành tuyến đường sắt đô thị",en:"Urban rail line operations manager"}],glossary:[{term:"CBTC",vi:"Hệ thống điều khiển tàu dựa trên truyền thông liên tục giữa tàu và thiết bị mặt đất.",en:"Communications-based train control using continuous train-to-wayside data links."},{term:"Headway",vi:"Giãn cách thời gian giữa hai đoàn tàu liên tiếp chạy cùng hướng.",en:"Time interval between two successive trains in the same direction."},{term:"RM",vi:"Chế độ lái tay hạn chế, tốc độ thấp, lái tàu tự quan sát đường, dùng khi mất cấp phép CBTC.",en:"Restricted manual mode at low speed on driver sight, used when CBTC authority is lost."},{term:"ATP",vi:"Bảo vệ tàu tự động, ngăn tàu vượt tốc độ hoặc vượt giới hạn cấp phép di chuyển.",en:"Automatic train protection that prevents overspeed and exceeding the movement authority."},{term:"Turnback",vi:"Thao tác đổi hướng chạy tàu tại ga cuối, gồm thời gian đổi buồng lái và kiểm tra.",en:"Reversing a train at a terminus, including cab change and checks."}],quiz:[{q:{vi:"Chạy một chiều 20 phút, quay đầu 5 phút tại mỗi ga cuối, giãn cách 5 phút. Cần bao nhiêu đoàn tàu vận doanh?",en:"One-way running time 20 minutes, 5-minute turnback at each terminus, 5-minute headway. How many trains are needed?"},options:{vi:["8 đoàn","10 đoàn","9 đoàn","12 đoàn"],en:["8 trains","10 trains","9 trains","12 trains"]},answer:1,explain:{vi:"Chu trình = 2 x 20 + 2 x 5 = 50 phút; 50 ÷ 5 = 10 đoàn tàu.",en:"Cycle = 2 x 20 + 2 x 5 = 50 minutes; 50 ÷ 5 = 10 trains."}},{q:{vi:"Khi đoàn tàu mất liên lạc CBTC, chế độ lái nào phù hợp?",en:"When a train loses CBTC communication, which driving mode is appropriate?"},options:{vi:["ATO","CM","Chạy tay tốc độ thường","RM theo lệnh điều độ"],en:["ATO","CM","Manual at normal speed","RM under OCC authority"]},answer:3,explain:{vi:"Không còn cấp phép di chuyển nên chỉ được chạy chế độ hạn chế, tốc độ thấp theo lệnh điều độ.",en:"Without a movement authority only restricted low-speed mode under OCC authority is allowed."}},{q:{vi:"Cấp trên yêu cầu cắt ATP để chạy nhanh và ghi giảm thời gian trễ. Bạn làm gì?",en:"A superior asks you to cut out ATP to run faster and under-report the delay. What do you do?"},options:{vi:["Từ chối, giữ chế độ an toàn, ghi đúng số liệu và báo cáo theo quy trình","Làm theo vì đang giờ cao điểm","Cắt ATP nhưng ghi đúng thời gian trễ","Không nghe máy để tránh trách nhiệm"],en:["Refuse, keep the safe mode, record true data and report per procedure","Comply because it is peak hour","Cut out ATP but log the true delay","Ignore the call to avoid responsibility"]},answer:0,explain:{vi:"Cắt thiết bị bảo vệ và làm sai lệch số liệu sự cố đều là vi phạm an toàn nghiêm trọng.",en:"Bypassing protection and falsifying incident data are both serious safety breaches."}},{q:{vi:"Cấp tự động hóa GoA4 theo IEC 62290 có nghĩa là gì?",en:"What does grade of automation GoA4 mean under IEC 62290?"},options:{vi:["Lái tay hoàn toàn","Có lái tàu giám sát ATO","Tự động hoàn toàn, không có nhân viên vận hành trên tàu","Chỉ có bảo vệ ATP"],en:["Fully manual driving","ATO with a driver supervising","Fully automatic with no staff on board","ATP protection only"]},answer:2,explain:{vi:"GoA4 là vận hành không người trên tàu (UTO), hệ thống tự xử lý cả tình huống bất thường.",en:"GoA4 is unattended train operation (UTO), with the system handling abnormal situations too."}}],tools_en:["Automatic train supervision (ATS) system","Control center displays & line diagrams","TETRA radio system","Power supply SCADA system","Passenger information system (PIS)"]}}})})(window.KKR);
